import { useEffect, useState } from 'react'
import { connect } from 'react-redux'
import { Button, Table, Alert, Modal, Spin } from 'antd'

import ClaimActions from '../.././../../redux/claims/actions'
import loadingActions from '../../../../../redux/loading/actions'
import errorActions from '../../../../../redux/error/actions'
import moment from 'moment'
import LayoutContentWrapper from '../../../../../components/utility/layoutWrapper'
import LayoutContent from '../../../../../components/utility/layoutContent'
import { withRouter } from 'react-router'
import { QuestionWrapper } from '../../InstantClaimConfiguration/index.style'

const {
  getGreenChannelData,
  getGreenChannelingList,
  resetReduxStateClaim
} = ClaimActions

const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

function GreenChannelConfigListing (props) {
  const [isOpenGreenChannelConfigDataModal, setIsOpenGreenChannelConfigDataModal] = useState(false)

  const {
    resetErrorRedux,
    resetLoadingRedux,
    resetReduxStateClaim,
    getGreenChannelingList,
    getGreenChannelData,
    greenChannelListingData,
    greenChannelConfigDataError,
    greenChannelConfigData = {},
    greenChannelConfigDataMessage,
    greenChannelConfigDataLoading,
    claimsInstantConfigurationListError,
    claimsInstantConfigurationListLoading
  } = props

  useEffect(() => {
    getGreenChannelingList()
  }, [getGreenChannelingList])

  useEffect(() => {
    return () => {
      resetReduxStateClaim([
        'greenChannelConfigData',
        'greenChannelListingData',
        'greenChannelConfigDataMessage'
      ])
    }
  }, [resetReduxStateClaim])

  const onViewAutoApprovalConfig = (configId) => {
    resetReduxStateClaim([
      'greenChannelConfigData',
      'greenChannelConfigDataMessage'
    ])
    getGreenChannelData({
      query: {
        custom_config_id: configId
      }
    })
    setIsOpenGreenChannelConfigDataModal(true)
  }

  const listingColumns = [
    {
      title: 'Action',
      dataIndex: 'config_id',
      key: 'config_id',
      render: (configId) => (
        <div>
          <div onClick={() => onViewAutoApprovalConfig(configId)}>View</div>
          /
          <a href={`add-green-channeling-config?configId=${configId}`}>Edit</a>
        </div>
      )
    },
    {
      title: 'Created At',
      dataIndex: 'created_at',
      key: 'created_by',
      render: (createdAt) => {
        return createdAt ? moment(createdAt).format('DD/MM/YYYY HH:mm:ss') : '-'
      }
    },
    {
      title: 'Created By',
      dataIndex: 'created_by',
      key: 'config_id'
    },
    {
      title: 'Configuration ID',
      dataIndex: 'config_id',
      key: 'config_id'
    },
    {
      title: 'Partner Product',
      dataIndex: 'partner_product_key',
      key: 'partner_product_key',
      render: (partner) => {
        if (Array.isArray(partner)) {
          return partner.join(', ')
        }
        return partner
      }
    },
    {
      title: 'Last Modified',
      dataIndex: 'updated_at',
      key: 'updated_at',
      render: (updatedAt) => {
        return updatedAt ? moment(updatedAt).format('DD/MM/YYYY HH:mm:ss') : '-'
      }
    },
    {
      title: 'Insurance Provider',
      dataIndex: 'insurance_provider',
      key: 'insurance_provider'
    }

  ]

  const addGreenChannelConfig = () => {
    const { history } = props

    history.push('add-green-channeling-config')
  }

  const handleCloseModal = () => {
    setIsOpenGreenChannelConfigDataModal(false)
    resetReduxStateClaim([
      'greenChannelConfigData',
      'greenChannelConfigDataMessage'
    ])
    resetErrorRedux(['GET_GREEN_CHANNELING_DATA'])
    resetLoadingRedux(['GET_GREEN_CHANNELING_DATA'])
  }

  return (
    <LayoutContentWrapper className='content-wrapper'>
      <Modal
        title='Green Channel Configuration Info'
        visible={isOpenGreenChannelConfigDataModal}
        onCancel={handleCloseModal}
        onOk={handleCloseModal}
        footer={null}
      >
        <Spin spinning={greenChannelConfigDataLoading}>
          {
            greenChannelConfigDataError
              ? (
                <Alert
                  type='error'
                  message={greenChannelConfigDataMessage}
                />
                )
              : null
          }
          {
            Object.keys(greenChannelConfigData).length
              ? (
                <>
                  <QuestionWrapper>
                    <div>Insurance Provider: </div>
                    <div>{greenChannelConfigData.insurance_provider || 'N/A'}</div>
                  </QuestionWrapper>
                  <QuestionWrapper>
                    <div>Partner Product: </div>
                    <div>
                      {
                        greenChannelConfigData.partner_product_key && Array.isArray(greenChannelConfigData.partner_product_key)
                          ? greenChannelConfigData.partner_product_key.join(',')
                          : 'N/A'
                      }
                    </div>
                  </QuestionWrapper>
                  <QuestionWrapper>
                    <div>Config Id: </div>
                    <div>{greenChannelConfigData.config_id || 'N/A'}</div>
                  </QuestionWrapper>
                  <QuestionWrapper>
                    <div>Created at: </div>
                    <div>
                      {greenChannelConfigData.created_at ? moment.utc(greenChannelConfigData.created_at).format('YYYY-MM-DD') : 'N/A'}
                    </div>
                  </QuestionWrapper>
                  <QuestionWrapper>
                    <div>End at: </div>
                    <div>
                      {greenChannelConfigData.end_date ? moment.utc(greenChannelConfigData.end_date).format('YYYY-MM-DD') : 'N/A'}
                    </div>
                  </QuestionWrapper>
                  <QuestionWrapper>
                    <div>Created By: </div>
                    <div>{greenChannelConfigData.created_by || 'N/A'}</div>
                  </QuestionWrapper>
                  <QuestionWrapper>
                    <div>Provider POC Email Id: </div>
                    <div>{greenChannelConfigData.poc_email_ids || 'N/A'}</div>
                  </QuestionWrapper>
                  <QuestionWrapper>
                    <div>Updated at:</div>
                    <div>{greenChannelConfigData.updated_at ? moment.utc(greenChannelConfigData.updated_at).format('YYYY-MM-DD') : 'N/A'}</div>
                  </QuestionWrapper>
                </>
                )
              : null
          }
        </Spin>
      </Modal>
      <LayoutContent>
        <div className='m-16 flex space-between'>
          <h1>
            Green Channel Config
          </h1>
          <div>
            <Button
              type='primary'
              onClick={addGreenChannelConfig}
            >
              Add Green Channel Config
            </Button>
          </div>
        </div>

        {
          claimsInstantConfigurationListError
            ? (
              <div>
                <Alert
                  type='error'
                  message='There was error while fetching custom claim listing'
                />
              </div>
              )
            : null
        }

        <Table
          columns={listingColumns}
          dataSource={greenChannelListingData}
          loading={claimsInstantConfigurationListLoading}
        />
      </LayoutContent>

    </LayoutContentWrapper>
  )
}

const mapStateToProps = (state) => ({
  greenChannelListingData: state.Claims.greenChannelListingData,
  greenChannelConfigData: state.Claims.greenChannelConfigData,
  greenChannelConfigDataMessage: state.Claims.greenChannelConfigDataMessage,
  greenChannelConfigDataLoading: state.Loading.GET_GREEN_CHANNELING_DATA,
  greenChannelConfigDataError: state.Error.GET_GREEN_CHANNELING_DATA,
  claimsInstantConfigurationListError: state.Error.GET_GREEN_CHANNELING_LIST,
  claimsInstantConfigurationListLoading: state.Loading.GET_GREEN_CHANNELING_LIST
})

export default withRouter(connect(mapStateToProps, {
  resetLoadingRedux,
  resetErrorRedux,
  getGreenChannelData,
  getGreenChannelingList,
  resetReduxStateClaim
})(GreenChannelConfigListing))
